"""v57 - prompt-quality engine: clash fixes, a framing/clarity pack for 1:1 images (full-body, product, macro, panels), and model profiles."""
import os, re, sys, glob
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from paths import FINAL
from famlib import P, run_mod, export_aoo_mod
from v53_build import _wr
CLARITY = P("Ultra-sharp, high-resolution image with crisp focus throughout, fine detail, clean edges, accurate natural colour and no blur, haze, noise or compression artefacts.; Razor-sharp, high-resolution image with fine detail, clean edges, natural colour and no blur, noise or artefacts.; Crisp, high-definition image, sharply focused from front to back, with clear edges, true colours and fine texture and no blur or digital noise.; Extremely sharp, detailed, high-resolution image with clean lines, accurate colour and no softness, haze or artefacts.")
RATIO = P("Square 1:1 frame.; The image is a square 1:1 frame.; Square composition, 1:1.")
PERSON_FULL = P("Wide-angle environmental portrait with the entire person visible from head to toe, with clear space above the head and below the feet and nothing cut off at any edge of the frame.; Full-length environmental portrait with the whole body, including hands and feet, fully inside the frame and generous margins on every side.; Wide environmental portrait with the complete figure centred, head to toe, and no part of the body touching or cropped by the frame edges.; Full-body shot from a comfortable distance, the whole person and a good amount of the surroundings in frame, nothing cropped.")
GROUP_FULL = P("Wide environmental group portrait with every person visible from head to toe, nobody cropped or cut off by any edge, and people arranged so that no one hides another.; Full-length group shot from a comfortable distance, all figures completely inside the frame with margin on every side and everyone's face visible.")
PERSON_STYLE = P("candid documentary photograph; editorial fashion photograph; natural-light lifestyle photograph; cinematic photograph with subtle film grain; clean contemporary magazine portrait; street photograph with a sense of place; travel photograph with true-to-life colour; studio-lit fashion photograph on a seamless backdrop")
LIGHT = P("soft, even light that shows clothing texture and skin detail clearly; warm directional light with gentle shadows; bright natural light with crisp detail and balanced contrast; diffused light with smooth tonal range; clean studio light with soft shadows")
FACE = P("Close-up portrait with the face and shoulders filling the frame, sharp focus on the eyes and skin texture, soft studio light and a plain neutral background.; Tight beauty portrait from the top of the head to the collarbone, sharp focus on the eyes, soft diffused light, plain background.")
GRID = P("The image is divided into a neat 2 by 2 grid of four equal panels with thin white dividers, each panel showing a different version of the same subject so the differences are easy to compare.; The square image is split into four equal panels by thin white lines, two across and two down, each panel showing a different variation.")
MACRO = P("Macro photograph, the whole subject inside the frame with margin around it, razor-sharp focus on the finest detail, soft diffused light and a softly blurred background.; Extreme close-up with sharp macro detail, even soft light and a plain neutral background.")
PRODUCT = P("Product photograph with the whole item shown, centred and completely inside the frame with space around it, on a plain seamless soft-grey surface, soft diffused studio light with a gentle shadow beneath, crisp detail on materials and edges.; Clean catalogue photograph, the entire item visible in a three-quarter view with generous margins, plain seamless pale backdrop, soft even light, sharp texture detail.")
ROOM = P("Interior photograph from a corner at eye height with a wide-angle lens, vertical lines kept straight and the entire room visible from floor to ceiling with every wall in frame, bright soft natural light mixed with the room's lamps, balanced exposure.; Wide interior view straight on, the whole space visible with nothing cropped, even natural light, architectural magazine style.")
BUILDING = P("Architectural photograph with the whole building visible from base to top with space around it, straight vertical lines, clear sky or soft overcast light and crisp detail on materials.; Full view of the structure with a little ground and sky around it, level horizon, soft natural light, sharp detail.")
VEHICLE = P("Three-quarter view with the entire vehicle inside the frame and margin on every side, clean uncluttered surroundings, soft natural light and crisp detail on paint, metal and tyres.")
LAND = P("Wide-angle landscape with a clear foreground, middle ground and background and no people in frame, natural light of the stated time and weather, rich tonal range.; Panoramic-feeling wide view with a level horizon, sharp detail from front to back, true-to-life colour.")
ANIMAL = P("Wildlife photograph with the whole animal visible inside the frame with space around it, subject sharp against a softly blurred natural background, natural light and true-to-life colour.; Full-body view of the whole animal with margin on every side, sharp focus on the eyes and coat or skin, natural light.")
PET = P("Pet photograph with the whole animal visible inside the frame and space around it, sharp focus on the eyes and coat, soft natural light, softly blurred background.")
FOOD = P("Food photograph from a 45-degree angle with the whole dish or item inside the frame and plenty of space around it, appetising natural window light, sharp focus on texture and moisture.; Overhead view of the whole table or plate with everything inside the frame, bright soft light and sharp detail.")
PLANT = P("Nature photograph with the whole plant inside the frame, sharp focus on the plant, natural soft light, true colour, shallow depth of field in the background.")
def build(final=FINAL):
    G = {}
    for k, v in dict(frame_clarity=CLARITY, frame_ratio=RATIO, frame_person_full=PERSON_FULL, frame_group_full=GROUP_FULL, frame_person_style=PERSON_STYLE, frame_light=LIGHT, frame_face=FACE, frame_grid=GRID, frame_macro=MACRO,
                     frame_product=PRODUCT, frame_room=ROOM, frame_building=BUILDING, frame_vehicle=VEHICLE, frame_landscape=LAND, frame_animal=ANIMAL, frame_pet=PET, frame_food=FOOD, frame_plant=PLANT).items(): G[k] = v
    C, R = '__frame_clarity__ __frame_ratio__', ''
    tail = '__frame_person_style__, __frame_person_full__ Lighting is __frame_light__.'
    G['frame_person_prompt'] = [f'{C} __any_create_random_person_w_clothes__ __pose_prompt_no_support__ __setting_prompt__ ' + tail.replace('__frame_person_style__', '__frame_person_style__')]
    G['frame_person_prompt_short'] = [f'{C} __any_person_age25_34_w_clothes_short__ __pose_prompt_no_support__ __setting_prompt__ ' + tail]
    for b in ('18_24', '25_34', '35_44', '45_54', '55_64', '65_74', '75_84', '85_94', '95_120'):
        G['frame_person_age%s_prompt' % b] = [f'{C} __any_person_age{b}_w_clothes_short__ __pose_prompt_no_support__ __setting_prompt__ ' + tail]
    G['frame_group_prompt'] = [f'{C} __group_prompt__ __setting_prompt__ __frame_person_style__, __frame_group_full__ Lighting is __frame_light__.']
    G['frame_face_prompt'] = [f'{C} __any_person_age35_44_w_clothes_short__ __frame_face__']
    G['frame_outfit_prompt'] = [f'{C} __any_create_random_person_base_short__ Clothing. __occasion_prompt__ Standing pose facing the camera. Clean fashion lookbook photograph, full-length with the entire outfit visible from head to toe including shoes, centred with margin on every side, plain seamless light-grey backdrop. Lighting is soft and even so fabric detail is clear.']
    for name, subj, comp in (('accessory', '__acc_hat_prompt__', 'product'), ('furniture', '__furn_all_prompt__', 'product'), ('tool', '__tool_prompt__', 'product'), ('tableware', '__ware_prompt__', 'product'), ('room', '__room_prompt_full__', 'room'), ('building', '__arch_prompt__', 'building'), ('vehicle', '__veh_prompt__', 'vehicle'),
                             ('landscape', '__setting_prompt__', 'landscape'), ('animal', '__animal_prompt__', 'animal'), ('insect', '__animal_insects_prompt__', 'macro'), ('food', '__food_prompt__', 'food'), ('table', '__table_setting_prompt__', 'food'), ('plant', '__plant_prompt__', 'plant'), ('pet', '__animal_dogs_prompt__', 'pet')):
        G['frame_%s_prompt' % name] = [f'{C} {subj} __frame_{comp}__']
    G['frame_animal_quad_prompt'] = [f'{C} The image is divided into four equal panels by thin white lines, two across and two down. Each panel shows a different animal, the whole animal entirely inside its own panel and nothing cut off by the panel edges, with natural light and true-to-life colour. Top left panel, an amazing wildlife photograph of __animal_prompt__ Top right panel, an amazing wildlife photograph of __animal_prompt__ Bottom left panel, an amazing wildlife photograph of __animal_prompt__ Bottom right panel, an amazing wildlife photograph of __animal_prompt__']
    G['frame_feature_grid_prompt'] = [f'{C} __frame_grid__ Each panel is a macro close-up of the same kind of feature on a different person. Panel 1, __body_nails__. Panel 2, __body_nails__. Panel 3, __body_nails__. Panel 4, __body_nails__. __frame_macro__',
                                      f'{C} __frame_grid__ Each panel is a close-up beauty portrait of a different adult with a different makeup look. Panel 1, __body_makeup__. Panel 2, __body_makeup__. Panel 3, __body_makeup__. Panel 4, __body_makeup__. Soft studio light, face fully visible in each panel.']
    G['frame_prompt'] = ['__frame_%s_prompt__' % n for n in ('person', 'group', 'outfit', 'accessory', 'furniture', 'room', 'building', 'vehicle', 'landscape', 'animal', 'food', 'plant', 'pet', 'table')]
    G['v57_entry_points'] = ['frame_prompt', 'frame_person_prompt', 'frame_person_prompt_short', 'frame_group_prompt', 'frame_face_prompt', 'frame_outfit_prompt', 'frame_animal_quad_prompt', 'frame_feature_grid_prompt']
    return G
def run(final): return run_mod(sys.modules[__name__], final)
def export_aoo(out): return export_aoo_mod(build(FINAL), out, skip=('frame_person_prompt', 'frame_person_prompt_short', 'frame_group_prompt', 'frame_face_prompt', 'frame_outfit_prompt', 'frame_prompt', 'frame_animal_quad_prompt', 'frame_feature_grid_prompt', 'frame_landscape_prompt') + tuple('frame_person_age%s_prompt' % b for b in ('18_24', '25_34', '35_44', '45_54', '55_64', '65_74', '75_84', '85_94', '95_120')))
if __name__ == '__main__': run(FINAL)
